951  trait CompactFullScalarRange extends { FullScalarRange, CompactFullRange[\ZZ32\] }
952      getter stride(): ZZ32 = 1
953      getter size(): ZZ32 = do
954          l = self.lower
955          r = self.upper
956          if l > r then 0 else narrow(r-l+1) end
957        end
958      getter isEmpty(): Boolean = self.lower > self.upper
959      getter indexValuePairs(): Indexed[\(ZZ32,ZZ32),ZZ32\] = do
960          l = self.lower
961          self.map[\(ZZ32,ZZ32)\](fn (i:ZZ32):(ZZ32,ZZ32) => (i-l,i))
962        end
963      getter indices(): Indexed[\ZZ32,ZZ32\] = do
964          l = self.lower
965          self.map[\ZZ32\](fn (i:ZZ32):(ZZ32,ZZ32) => (i-l))
966        end
967      getter asExprString():String = self.lower ":" self.upper
968  
969      opr[i:ZZ32]: ZZ32 =
970          if i NOTIN self.bounds then throw IndexOutOfBounds(self.bounds,i)
971          else i+self.lower end
972      opr IN(n:ZZ32, self): Boolean = self.lower <= n <= self.upper
973      indexOf(n:ZZ32):Maybe[\ZZ32\] = if (n IN self) then Just[\ZZ32\](n - self.lower) else Nothing[\ZZ32\] end
974      shiftLeft(amount: ZZ32): CompactFullScalarRange = (self.lower - amount) : (self.upper - amount)
975      shiftRight(amount: ZZ32): CompactFullScalarRange (* ensures { |outcome| = |self| } *)
